-- Round 3: places, place owners, event hosts and the user nickname
-- (SPEC §9.2, §9.4, §9.8, §11; D-095–D-098, D-105, D-110).
--
-- Generated by `prisma migrate dev --create-only`, then edited by hand in
-- exactly two places (keep it that way, or the next `migrate dev` proposes a
-- reset, F-009):
--   (a) events.place_id is added NULLABLE here. The data section below links
--       every existing event to a place and only then sets it NOT NULL.
--       The composite FK may be created before that: with MATCH SIMPLE, rows
--       with a NULL place_id are not checked.
--   (b) the data section (D-022 → places) and the CHECK constraints are
--       appended at the end.
-- Prisma sends the script as one implicit transaction, so any failure rolls
-- everything back.

-- AlterTable
-- Hand edit (a): nullable until the data section has linked every event.
ALTER TABLE "events" ADD COLUMN     "place_id" TEXT,
ALTER COLUMN "location_text" DROP NOT NULL;

-- AlterTable
ALTER TABLE "users" ADD COLUMN     "nickname" TEXT;

-- CreateTable
CREATE TABLE "places" (
    "id" TEXT NOT NULL,
    "club_id" TEXT NOT NULL,
    "name" TEXT NOT NULL,
    "name_key" TEXT NOT NULL,
    "address" TEXT,
    "description" TEXT,
    "created_by_id" TEXT NOT NULL,
    "archived_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "places_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "place_owners" (
    "place_id" TEXT NOT NULL,
    "club_id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "place_owners_pkey" PRIMARY KEY ("place_id","user_id")
);

-- CreateTable
CREATE TABLE "event_hosts" (
    "event_id" TEXT NOT NULL,
    "user_id" TEXT NOT NULL,
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "event_hosts_pkey" PRIMARY KEY ("event_id","user_id")
);

-- CreateIndex
CREATE INDEX "places_club_id_idx" ON "places"("club_id");

-- CreateIndex
CREATE UNIQUE INDEX "places_id_club_id_key" ON "places"("id", "club_id");

-- CreateIndex
CREATE UNIQUE INDEX "places_club_id_name_key_active_key" ON "places"("club_id", "name_key") WHERE ("archived_at" IS NULL);

-- CreateIndex
CREATE INDEX "place_owners_user_id_club_id_idx" ON "place_owners"("user_id", "club_id");

-- CreateIndex
CREATE INDEX "event_hosts_user_id_idx" ON "event_hosts"("user_id");

-- CreateIndex
CREATE INDEX "events_place_id_idx" ON "events"("place_id");

-- AddForeignKey
ALTER TABLE "events" ADD CONSTRAINT "events_place_id_club_id_fkey" FOREIGN KEY ("place_id", "club_id") REFERENCES "places"("id", "club_id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "places" ADD CONSTRAINT "places_club_id_fkey" FOREIGN KEY ("club_id") REFERENCES "clubs"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "places" ADD CONSTRAINT "places_created_by_id_fkey" FOREIGN KEY ("created_by_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "place_owners" ADD CONSTRAINT "place_owners_place_id_club_id_fkey" FOREIGN KEY ("place_id", "club_id") REFERENCES "places"("id", "club_id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "place_owners" ADD CONSTRAINT "place_owners_user_id_club_id_fkey" FOREIGN KEY ("user_id", "club_id") REFERENCES "memberships"("user_id", "club_id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "place_owners" ADD CONSTRAINT "place_owners_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "event_hosts" ADD CONSTRAINT "event_hosts_event_id_fkey" FOREIGN KEY ("event_id") REFERENCES "events"("id") ON DELETE CASCADE ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "event_hosts" ADD CONSTRAINT "event_hosts_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ─── Hand edit (b): data section (D-022 → places, D-097) ────────────────────
-- Every round-2 event gets a place, one per (club, name key):
--   * name key = the place-name key of src/server/domain/places/name.ts
--     (placeNameKey: NFC, lower case, ALL whitespace removed). The whitespace
--     class mirrors JavaScript's \s: POSIX [[:space:]] plus U+00A0, U+1680,
--     U+2000–U+200A, U+2028, U+2029, U+202F, U+205F, U+3000 and U+FEFF
--     (Postgres' own \s misses NBSP). lower() follows the database's
--     LC_CTYPE: C.UTF-8 (dev, test, Neon) folds Æ/Ø/Å like JS (TG-036).
--     tests/integration/round3-migration.itest.ts proves the parity.
--   * name = the most used spelling (whitespace collapsed), then the most
--     recently used, then alphabetical. Always ≤ 120 characters, so lossless.
--     An empty name falls back to "Ukendt sted".
--   * created_by and created_at come from the club's earliest event with that key.
--   * address = the name when it contains a digit (keeps round 2's "Åbn i kort"
--     for street-like texts); otherwise NULL. No description and no owners:
--     ownership is self-claimed (§9.4).
--   * Ids are UUIDv4 from gen_random_uuid(); isValidId accepts every UUID.
-- Every existing event gets its creator as host (§9.2: no owners → the creator).

-- Empty club descriptions become NULL (the CHECK below allows 1–300 characters).
UPDATE "clubs" SET "description" = NULLIF(btrim("description"), '') WHERE "description" IS NOT NULL;

CREATE TEMP TABLE "r3_event_texts" AS
SELECT e."id" AS event_id, e."club_id", e."created_by_id", e."starts_at", e."created_at",
  COALESCE(NULLIF(btrim(regexp_replace(normalize(e."location_text", NFC),
    '[[:space:]   -     　﻿]+', ' ', 'g')), ''),
    'Ukendt sted') AS name,
  COALESCE(NULLIF(regexp_replace(lower(normalize(e."location_text", NFC)),
    '[[:space:]   -     　﻿]', '', 'g'), ''),
    'ukendtsted') AS name_key
FROM "events" e
WHERE e."place_id" IS NULL;

CREATE TEMP TABLE "r3_places" AS
SELECT gen_random_uuid()::text AS id, s.club_id, s.name_key, s.name, f.created_by_id, f.created_at
FROM (
  SELECT DISTINCT ON (club_id, name_key) club_id, name_key, name
  FROM (
    SELECT club_id, name_key, name, count(*) AS uses, max(starts_at) AS last_used
    FROM "r3_event_texts"
    GROUP BY club_id, name_key, name
  ) v
  ORDER BY club_id, name_key, uses DESC, last_used DESC, name
) s
JOIN (
  SELECT DISTINCT ON (club_id, name_key) club_id, name_key, created_by_id, created_at
  FROM "r3_event_texts"
  ORDER BY club_id, name_key, starts_at, event_id
) f USING (club_id, name_key);

-- No ON CONFLICT: a dedup bug must fail loudly on places_club_id_name_key_active_key.
INSERT INTO "places" ("id", "club_id", "name", "name_key", "address", "created_by_id", "created_at", "updated_at")
SELECT id, club_id, name, name_key, CASE WHEN name ~ '[0-9]' THEN name END, created_by_id, created_at, now()
FROM "r3_places";

UPDATE "events" e SET "place_id" = p.id
FROM "r3_event_texts" t JOIN "r3_places" p USING (club_id, name_key)
WHERE e."id" = t.event_id;

INSERT INTO "event_hosts" ("event_id", "user_id")
SELECT "id", "created_by_id" FROM "events"
ON CONFLICT DO NOTHING;

DROP TABLE "r3_event_texts";
DROP TABLE "r3_places";

-- Fails loudly if any event was not linked.
ALTER TABLE "events" ALTER COLUMN "place_id" SET NOT NULL;

-- ─── Hand edit (b): CHECK constraints (SPEC §11, D-034) ─────────────────────
-- Prisma cannot express CHECKs and ignores them when diffing (F-004: CHECKs
-- only, never raw indexes or FKs). The app cleans and validates first
-- (src/lib/validation/*, src/server/domain/*); these guard every writer.
-- events_location_text_length_check (round 2) stays: it lets NULL through.

ALTER TABLE "users"
  ADD CONSTRAINT "users_nickname_length_check"
  CHECK ("nickname" IS NULL OR char_length(btrim("nickname")) BETWEEN 1 AND 40);

ALTER TABLE "clubs"
  ADD CONSTRAINT "clubs_description_length_check"
  CHECK ("description" IS NULL OR char_length(btrim("description")) BETWEEN 1 AND 300);

ALTER TABLE "places"
  ADD CONSTRAINT "places_name_length_check"
  CHECK (char_length(btrim("name")) BETWEEN 1 AND 120);

ALTER TABLE "places"
  ADD CONSTRAINT "places_name_key_not_empty_check"
  CHECK ("name_key" <> '');

ALTER TABLE "places"
  ADD CONSTRAINT "places_address_length_check"
  CHECK ("address" IS NULL OR char_length(btrim("address")) BETWEEN 1 AND 200);

ALTER TABLE "places"
  ADD CONSTRAINT "places_description_length_check"
  CHECK ("description" IS NULL OR char_length(btrim("description")) BETWEEN 1 AND 1000);
